-- ============================================================================
-- DO NOT EDIT THIS FILE ONCE IT HAS BEEN APPLIED TO ANY DATABASE.
-- Until then it may still change. After it is applied, every change goes in a
-- new migration file with a later timestamp.
-- ============================================================================
--
-- Client schedules: appointments, site surveys, calls and follow-ups per lead,
-- with the outcome of the Google Calendar sync and of the email to the lead.
--
-- Add-only: one new table, two trigger functions, its policies and one new
-- insert policy on automation_events. Nothing here alters, drops or writes an
-- existing object or row. The server actions mirror the next date into
-- leads.appointment / site_survey / follow_up_date at runtime, one lead at a
-- time; there is no backfill.
--
-- Depends on 20261112090000_whatsapp.sql (private.set_updated_at,
-- private.current_sales_user_id, private.owns_lead, automation_events).
-- NOT applied to production by the developer. The project owner reviews and
-- applies it (see docs/schedules.md).

-- 1. table --------------------------------------------------------------------

create table public.lead_schedules (
    id uuid primary key default gen_random_uuid(),
    -- on delete set null: a schedule never blocks deleting a lead. The trigger
    -- in section 3 then cancels the orphaned row, so it leaves every calendar
    -- view; the delete action removes the Google event first.
    lead_id bigint references public.leads (id) on delete set null,
    sales_id uuid references public.sales_users (id) on delete set null,
    kind text not null,
    title text not null,
    starts_at timestamptz not null,
    ends_at timestamptz,
    all_day boolean not null default false,
    location text,
    notes text,
    status text not null default 'scheduled',
    previous_starts_at timestamptz,
    reschedule_count integer not null default 0,
    ics_sequence integer not null default 0,
    completed_at timestamptz,
    cancelled_at timestamptz,
    notify_lead boolean not null default false,
    lead_email_snapshot text,
    google_event_id text,
    google_sync_status text not null default 'not_connected',
    google_error text,
    google_synced_at timestamptz,
    email_status text not null default 'not_requested',
    email_error text,
    email_sent_at timestamptz,
    email_message_id text,
    created_by uuid references public.sales_users (id) on delete set null,
    updated_by uuid references public.sales_users (id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint lead_schedules_kind_check
        check (kind = any (array['appointment', 'site_survey', 'call', 'follow_up'])),
    constraint lead_schedules_status_check
        check (status = any (array['scheduled', 'done', 'cancelled'])),
    constraint lead_schedules_google_sync_status_check
        check (google_sync_status = any (array['not_connected', 'pending', 'synced', 'failed'])),
    constraint lead_schedules_email_status_check
        check (email_status = any (array['not_requested', 'not_connected', 'sent', 'failed'])),
    constraint lead_schedules_title_length check (char_length(title) between 1 and 200),
    constraint lead_schedules_location_length check (location is null or char_length(location) <= 300),
    constraint lead_schedules_notes_length check (notes is null or char_length(notes) <= 2000),
    constraint lead_schedules_ends_after_starts check (ends_at is null or ends_at > starts_at),
    constraint lead_schedules_follow_up_has_no_end check (kind <> 'follow_up' or ends_at is null)
);

comment on table public.lead_schedules is 'Dated plans per lead (appointment, site survey, call, follow-up). Times in UTC; FSI works in Asia/Makassar (UTC+8).';
comment on column public.lead_schedules.id is 'Schedule id. Also the stable iCalendar UID and the Google event id (hyphens removed).';
comment on column public.lead_schedules.lead_id is 'The lead or customer. Null only after the lead was deleted (the row is then cancelled).';
comment on column public.lead_schedules.sales_id is 'Salesperson responsible (sales_users.id). Null when unassigned.';
comment on column public.lead_schedules.kind is 'appointment, site_survey, call or follow_up.';
comment on column public.lead_schedules.title is 'Short title shown in the CRM and on the calendar event.';
comment on column public.lead_schedules.starts_at is 'Start (UTC). For an all-day item, 00:00 Bali time of that day.';
comment on column public.lead_schedules.ends_at is 'End (UTC). Always null for follow-ups.';
comment on column public.lead_schedules.all_day is 'True when the item has a day but no time.';
comment on column public.lead_schedules.location is 'Where it happens, free text.';
comment on column public.lead_schedules.notes is 'Internal notes. Never sent to the lead.';
comment on column public.lead_schedules.status is 'scheduled, done or cancelled. Rows are cancelled, never deleted.';
comment on column public.lead_schedules.previous_starts_at is 'Start before the latest reschedule, kept as history.';
comment on column public.lead_schedules.reschedule_count is 'How many times the start was moved.';
comment on column public.lead_schedules.ics_sequence is 'iCalendar SEQUENCE; incremented on every reschedule and on cancel.';
comment on column public.lead_schedules.completed_at is 'When it was marked done.';
comment on column public.lead_schedules.cancelled_at is 'When it was cancelled.';
comment on column public.lead_schedules.notify_lead is 'Whether staff asked to email the lead with a calendar file.';
comment on column public.lead_schedules.lead_email_snapshot is 'The address the last email went to (or was attempted to), as it was at send time.';
comment on column public.lead_schedules.google_event_id is 'Event id on GOOGLE_CALENDAR_ID once created.';
comment on column public.lead_schedules.google_sync_status is 'not_connected (no Google keys), pending, synced or failed.';
comment on column public.lead_schedules.google_error is 'Plain-language reason of the last failed Google sync.';
comment on column public.lead_schedules.google_synced_at is 'Last successful Google sync.';
comment on column public.lead_schedules.email_status is 'not_requested, not_connected (no email keys), sent or failed.';
comment on column public.lead_schedules.email_error is 'Plain-language reason of the last failed or skipped email.';
comment on column public.lead_schedules.email_sent_at is 'When the last email was accepted by the email service.';
comment on column public.lead_schedules.email_message_id is 'The email service''s id of the last email.';
comment on column public.lead_schedules.created_by is 'sales_users.id of who created it. Null when created by the WhatsApp assistant.';
comment on column public.lead_schedules.updated_by is 'sales_users.id of who changed it last.';
comment on column public.lead_schedules.created_at is 'Row created.';
comment on column public.lead_schedules.updated_at is 'Row changed; used to refuse stale edits.';

create index idx_lead_schedules_lead_starts on public.lead_schedules (lead_id, starts_at);
create index idx_lead_schedules_sales_starts on public.lead_schedules (sales_id, starts_at);
create index idx_lead_schedules_scheduled_starts on public.lead_schedules (starts_at) where status = 'scheduled';

-- 2. updated_at ---------------------------------------------------------------

create trigger lead_schedules_set_updated_at
    before update on public.lead_schedules
    for each row execute function private.set_updated_at();

-- 3. a deleted lead's schedules leave the calendar ------------------------------
-- When on delete set null clears lead_id on a row still scheduled, cancel it.
-- If a Google event exists and was not removed beforehand (a delete from the
-- legacy app), mark the sync failed with the reason, so it shows up for review.

create or replace function private.cancel_schedule_of_deleted_lead()
returns trigger
language plpgsql
set search_path to ''
as $$
begin
    if old.lead_id is not null and new.lead_id is null and new.status = 'scheduled' then
        new.status = 'cancelled';
        new.cancelled_at = now();
        if new.google_event_id is not null then
            new.google_sync_status = 'failed';
            new.google_error = 'The lead was deleted. Remove this event from Google Calendar by hand.';
        end if;
    end if;
    return new;
end;
$$;

create trigger lead_schedules_cancel_on_lead_delete
    before update of lead_id on public.lead_schedules
    for each row execute function private.cancel_schedule_of_deleted_lead();

-- 4. access -------------------------------------------------------------------

alter table public.lead_schedules enable row level security;

-- Supabase grants every privilege on new public tables to anon and authenticated
-- by default. Take those away. Nobody deletes through the API: cancel instead.
revoke all on public.lead_schedules from anon, authenticated;
grant select, insert, update on public.lead_schedules to authenticated;
grant all on public.lead_schedules to service_role;

create policy lead_schedules_admin_select on public.lead_schedules
    for select to authenticated
    using ((select public.is_admin()));
create policy lead_schedules_admin_insert on public.lead_schedules
    for insert to authenticated
    with check ((select public.is_admin()));
create policy lead_schedules_admin_update on public.lead_schedules
    for update to authenticated
    using ((select public.is_admin()))
    with check ((select public.is_admin()));

-- Everyone else: only rows on a lead assigned to them, owned by them or unowned.
create policy lead_schedules_own_select on public.lead_schedules
    for select to authenticated
    using (
        lead_id is not null
        and (select private.owns_lead(lead_id))
        and (sales_id is null or sales_id = (select private.current_sales_user_id()))
    );
create policy lead_schedules_own_insert on public.lead_schedules
    for insert to authenticated
    with check (
        lead_id is not null
        and (select private.owns_lead(lead_id))
        and (sales_id is null or sales_id = (select private.current_sales_user_id()))
        and created_by = (select private.current_sales_user_id())
    );
create policy lead_schedules_own_update on public.lead_schedules
    for update to authenticated
    using (
        lead_id is not null
        and (select private.owns_lead(lead_id))
        and (sales_id is null or sales_id = (select private.current_sales_user_id()))
    )
    with check (
        lead_id is not null
        and (select private.owns_lead(lead_id))
        and (sales_id is null or sales_id = (select private.current_sales_user_id()))
    );

-- 5. automation_events: schedule failures --------------------------------------
-- A failed Google sync or email is logged for review under the name of the
-- person who triggered it, for a lead they may see. The existing policies stay
-- as they are; this one only adds the two schedule event types.

create policy automation_events_insert_schedule on public.automation_events
    for insert to authenticated
    with check (
        type = any (array['schedule_google_failed', 'schedule_email_failed'])
        and actor_sales_id = (select private.current_sales_user_id())
        and conversation_id is null
        and lead_id is not null
        and ((select public.is_admin()) or (select private.owns_lead(lead_id)))
    );
